mapper.select:
SELECT SD.ID, SD.CREATE_TIME, SDA.AREA_ID, SD.ENABLE_STATUS, SD.CONNECT_STATUS, SD.DEVICE_NAME, SA.AREA_NAME, SA.PID, SD.DEVICE_TYPE, SD.DEVICE_VENDOR, SD.IS_SYNC, SD.DEVICE_TAG, SD.DEVICE_CAPABILITY FROM SMT_DEVICE SD LEFT JOIN SMT_DEVICE_AREA SDA ON SD. ID = SDA.DEVICE_ID LEFT JOIN SMT_AREA SA ON SA. ID = SDA.AREA_ID
AND SDA.AREA_ID IN( SELECT SA."ID" FROM SMT_AREA SA
AND SA.PARK_ID = #{query.parkId}
AND SA.PID = #{query.parAreaId}
AND SA."ID" = #{query.areaId}
)
AND SD.ID IN( SELECT SA.DEVICE_ID FROM SMT_DEVICE_TAG_RELATION SA
AND SA.TAG_ID IN
#{tempId}
)
and SD.DEVICE_NAME LIKE CONCAT(CONCAT('%',#{query.deviceName}),'%')
AND SD.PARK_ID IN
#{tempId}
AND SD.ENABLE_STATUS = #{query.enableStatus}
AND SD.CONNECT_STATUS = #{query.connectStatus}
AND SD.DEVICE_TYPE = #{query.deviceType}
AND SD.DEVICE_TAG = #{query.deviceTag}
ORDER BY SA.AREA_NAME,SD.DEVICE_NAME DESC

SELECT SP. ID AS VALUE, SP.PARK_NAME AS LABEL FROM SMT_PARK SP
AND SP.ID IN
#{tempId}

SELECT SA. ID AS VALUE, SA.AREA_NAME AS LABEL FROM SMT_AREA SA
AND SA.PARK_ID = #{parkId}
AND SA.PID = #{pId}

SELECT SD. ID FROM SMT_DEVICE SD
SD.IS_SYNC != 1
AND SD.PARK_ID = #{parkId}
